def gen(rng):
    from math import gcd
    def fmt(cases):
        return str(len(cases)) + '\n' + '\n'.join(' '.join(map(str, c)) for c in cases)
    def cross(ax, ay, bx, by, cx, cy):
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
    def tri(R):
        while True:
            v = [rng.randint(-R, R) for _ in range(6)]
            if cross(*v) != 0:
                return v
    def point(v, R):
        k = rng.randint(0, 5)
        x1, y1, x2, y2, x3, y3 = v
        if k == 0:
            return rng.choice([(x1, y1), (x2, y2), (x3, y3)])
        if k == 1 or k == 2:
            (ax, ay), (bx, by) = rng.choice([((x1, y1), (x2, y2)), ((x2, y2), (x3, y3)), ((x3, y3), (x1, y1))])
            g = gcd(abs(bx - ax), abs(by - ay))
            s = rng.randint(0, g)
            return (ax + (bx - ax) // g * s, ay + (by - ay) // g * s)
        if k == 3:
            (ax, ay), (bx, by) = rng.choice([((x1, y1), (x2, y2)), ((x2, y2), (x3, y3)), ((x3, y3), (x1, y1))])
            px, py = 2 * bx - ax, 2 * by - ay
            if abs(px) <= R and abs(py) <= R:
                return (px, py)
        lo_x, hi_x = min(x1, x2, x3), max(x1, x2, x3)
        lo_y, hi_y = min(y1, y2, y3), max(y1, y2, y3)
        if k == 4:
            return (rng.randint(lo_x, hi_x), rng.randint(lo_y, hi_y))
        return (rng.randint(-R, R), rng.randint(-R, R))
    def cases(t, R):
        out = []
        for _ in range(t):
            v = tri(R)
            out.append(v + list(point(v, R)))
        return out
    tests = [fmt([[0, 0, 4, 0, 0, 3, 1, 1], [0, 0, 4, 0, 0, 3, 4, 3], [0, 0, 4, 0, 0, 3, 2, 0]]),
             fmt([[-2, -2, 6, -2, 2, 4, 8, -2], [-2, -2, 6, -2, 2, 4, 2, 4], [-2, -2, 6, -2, 2, 4, 0, 0]]),
             fmt([[0, 0, 1, 0, 0, 1, 1, 1]]), fmt([[0, 0, 1, 0, 0, 1, 0, 0]]),
             fmt([[-1000000, -1000000, 1000000, -1000000, 0, 1000000, 0, 0]]),
             fmt([[-1000000, -1000000, 1000000, -1000000, 0, 1000000, 1000000, 1000000]])]
    for R in (3, 5, 10, 50):
        for _ in range(3):
            tests.append(fmt(cases(rng.randint(3, 6), R)))
    tests.append(fmt(cases(2000, 4)))
    tests.append(fmt(cases(30000, 1000000)))
    tests.append(fmt(cases(30000, 1000000)))
    tests.append(fmt(cases(30000, 20)))
    return tests

